            events,
            diagnostics,
            trivia,
            self.state.list_tightness,
            self.state.list_item_indents,
            self.state.quote_indents,
        )
    }
}

fn count_leading_indent(text: &str) -> usize {
    let mut count = 0usize;
    for c in text.chars() {
        match c {
            ' ' => count += 1,
            '\t' => count += TAB_STOP_SPACES,
            _ => break,
        }
    }
    count
}

