///
/// Per CommonMark §4.5, a backtick fence's info string may not contain backtick
/// characters, so such a line is not a valid code fence. Callers should emit a
/// diagnostic and parse the line as a paragraph. Tilde fences are unaffected
/// and always return `None`.
pub(crate) fn backtick_info_stray_backtick(p: &mut MarkdownParser) -> Option<TextRange> {
    p.lookahead(|p| {
        if !p.at_start_of_input() && !is_line_start_within_indent(p, MAX_BLOCK_PREFIX_INDENT) {
            return None;
        }
        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);

        let start: usize = p.cur_range().start().into();
        let rest = p.source_after_current();
        let (fence_char, fence_len) = detect_fence(rest)?;
        if fence_char != '`' {
            return None;
        }

        // The info string is the remainder of the current line after the fence
        // run. Backticks are single-byte, so `fence_len` chars == `fence_len`
        // bytes and the first backtick after the fence run is the stray one.
        let line_rest = rest[fence_len..].split(['\n', '\r']).next().unwrap_or("");
        let offset = line_rest.find('`')?;
        let abs = start + fence_len + offset;
        Some(TextRange::new(
            TextSize::from(abs as u32),
            TextSize::from((abs + 1) as u32),
        ))
